// Include necessary libraries and headers for peripheral and utility functions
#include <xc.h>
#include <string.h> // para la función strcmp()
#include "config.h"
#include "usart.h"
#include <stdint.h> //para uint8_t,uint16_t,etc
#include <stdio.h>  //para la funcion "sprintf"
#include "mapfunc.h"
#include <stdbool.h>
char dato_rx[16];
int result;
long reg = 0;
char read;
int uread = 0;
//unsigned char valor_pwm;
void setup(){
    
    ADCON1 = 0x0F;                          //todos los pines del PORTA,PORTB como digitales
    OSCCON = 0x72;                          //Oscilador a 8 MHz
    TRISB = 0x00;                           //Port B as Digital Outputs
    PR2 = 0x3E;                             // Valor del periodo
    CCPR1L = 0;                             // Inicia el CCP1 en 0
    TRISCbits.TRISC2 = 0;                   // Pin C2 como salida
    T2CON = 0x03;                           // Configuracion del timer 2
    CCP1CON = 0x0C;                         // Configura el CCP1 en modo PWM
    TMR2 = 0;                               // Timer 2 en 0
    T2CONbits.TMR2ON = 1; 
    Uart_Init(9600);
}
void main(void) {
    setup(); // Initialize peripherals
    while (1) {
        // State: waiting for mode select command ('a' or 'b') via UART
        if (!uread) {
            if (Uart_Available() > 0) { // If UART has data
                read = Uart_Read();     // Read one byte
                //Uart_Read_String(dato_rx, sizeof(dato_rx)); // Option for string read (commented out)

                // Set mode when 'a' or 'b' command is received
                if (read == 'a') {
                    reg = 100;         // Set reference value for mode 'a'
                    uread = 1;         // Switch state: ready for processing
                }
                else if (read == 'b') {
                    reg = 200;         // Set reference value for mode 'b'
                    uread = 1;         // Switch state: ready for processing
                }
            }
        }
            
        // State: processing input value for selected mode
        else {
            if (uread) {
                if (Uart_Available() > 0) { // If UART has a value
                    Uart_Read_String(dato_rx, sizeof(dato_rx)); // Read value as string
                    result = atoi(dato_rx);      // Convert to integer
                    PORTB = result;              // Output result on PORTB

                    // Map input result to PWM value (0-250 scaled depending on reg)
            unsigned long valor_pwm = mapn(result, 0, reg, 0, 250);
                    CCPR1L = (valor_pwm >> 2);   // Update PWM duty cycle register (shifted, max 62)

                    // Reset logic: if received string is "0", clear PWM and go back to waiting for mode
                    if (reg == 100 && strcmp(dato_rx, "0") == 0) {
                        CCPR1L = 0;   // Stop PWM
                        uread = 0;    // Go back to waiting mode
            }
                    else if (reg == 200 && strcmp(dato_rx, "0") == 0) {
                        CCPR1L = 0;   // Stop PWM
                        uread = 0;    // Go back to waiting mode
            }
                    // Additional conditions can be added here for other commands
                }
            }
        }
    }
}
